import csv,io,tempfile,os
samples=['a,b\r\nc,d\r\ne,f','a,b\nc,d\ne,f','a,"x\ny",z\r\nq,r,s','a,b\rc,d\re,f','a,"x\r\ny",z\r\nq,r,s']
for s in samples:
 print('SAMPLE',repr(s))
 for mode in ['stringio','file']:
  try:
   if mode=='stringio':
    r=csv.reader(io.StringIO(s,newline=''),strict=True)
   else:
    fd,path=tempfile.mkstemp();os.write(fd,s.encode());os.close(fd)
    f=open(path,newline='',encoding='utf-8');r=csv.reader(f,strict=True)
   print(mode,list(r))
   if mode=='file':f.close();os.unlink(path)
  except Exception as e: print(mode,'ERR',type(e),e)
